     "الِانْتِقَالُ وَالسَّفَرُ مِنْ مَكَانٍ إِلَى آخَرَ.",
     "مَجْمُوعَةُ الصِّفَاتِ الَّتِي تُمَيِّزُ الشَّخْصَ عَنْ غَيْرِهِ.",
     "ثَرِيٌّ، كَثِيرُ الْمَالِ."
