 "rattib": [
  {
   "n": 1,
   "s": "أَنْتَ قَلِقٌ يَا وَلَدِي، مَاذَا بِكَ؟!"
  },
  {
   "n": 1,
   "s": "أُرِيدُ الزَّوَاجَ يَا أُمِّي، وَلَا أَجِدُ الْفَتَاةَ الْمُنَاسِبَةَ."
  },
  {
   "n": 1,
   "s": "هَذِهِ لَيْسَتْ مُشْكِلَةً. هُنَاكَ فَتَيَاتٌ كَثِيرَاتٌ مُنَاسِبَاتٌ لِلزَّوَاجِ."
  },
  {
   "n": 1,
   "s": "هَلْ تَعْرِفِينَ وَاحِدَةً مُنَاسِبَةً؟"
  },
  {
   "n": 1,
   "s": "هَذِهِ غَيْرُ مُنَاسِبَةٍ! إِنَّهَا فَقِيرَةٌ، لَا مَالَ لَهَا."
  },
  {
   "n": 1,
   "s": "مَا رَأْيُكَ فِي زَيْنَبَ بِنْتِ عَبْدِ اللهِ؟"
  },
  {
   "n": 1,
   "s": "هُنَاكَ هُدَى بِنْتُ عَبْدِ الْعَزِيزِ."
  },
  {
   "n": 1,
   "s": "سَمِعْتُ أَنَّهَا ذَاتُ مَالٍ وَجَمَالٍ، وَلَكِنِّي أُرِيدُ الْحَسَبَ وَالنَّسَبَ."
  },
  {
   "n": 1,
   "s": "تُرِيدُ الْمَالَ وَالْجَمَالَ وَالْحَسَبَ وَالنَّسَبَ. هَذِهِ لَا تُحَقِّقُ السَّعَادَةَ!"
  },
  {
   "n": 1,
   "s": "مَا الَّذِي يُحَقِّقُ السَّعَادَةَ إِذَنْ؟!"
  },
  {
   "n": 1,
   "s": "إِذَا أَرَدْتَ السَّعَادَةَ، فَعَلَيْكَ بِذَاتِ الدِّينِ."
  },
  {
   "n": 2,
   "s": "فِي الْحَيَاةِ الزَّوْجِيَّةِ خَيْرٌ كَثِيرٌ لِلزَّوْجِ وَلِلزَّوْجَةِ وَلِلْأَوْلَادِ."
  },
  {
   "n": 2,
   "s": "وَمَعَ ذَلِكَ تَظْهَرُ -أَحْيَانًا- بَعْضُ الْمُشْكِلَاتِ فِي حَيَاةِ الزَّوْجَيْنِ."
  },
  {
   "n": 2,
   "s": "عَلَيْنَا أَنْ نَعْرِفَ هَذِهِ الْحَقِيقَةَ قَبْلَ الزَّوَاجِ."
  },
  {
   "n": 3,
   "s": "أُرِيدُ أَنْ أَتْرُكَ زَوْجَتِي."
  },
  {
   "n": 3,
   "s": "إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ. مَاذَا هُنَاكَ؟!"
  },
  {
   "n": 3,
   "s": "لَا تُحِبُّهَا؟! كَيْفَ عِشْتَ مَعَهَا كُلَّ هَذِهِ السَّنَوَاتِ؟!"
  },
  {
   "n": 3,
   "s": "لَا أَدْرِي... لَا أَدْرِي... لَا أُحِبُّهَا."
  },
  {
   "n": 3,
   "s": "كُنْتُ أُحِبُّهَا فِعْلًا، وَلَكِنَّهَا تَغَيَّرَتْ كَثِيرًا."
  },
  {
   "n": 3,
   "s": "هَلْ تَكَلَّمْتَ مَعَهَا فِي هَذَا الْأَمْرِ؟"
  },
  {
   "n": 3,
   "s": "تَكَلَّمْتُ مَعَهَا كَثِيرًا، وَلَكِنَّهَا عَنِيدَةٌ."
  },
  {
   "n": 3,
   "s": "نَعَمْ، أَصْبَحْتُ أَسْهَرُ كَثِيرًا خَارِجَ الْبَيْتِ."
  },
  {
   "n": 3,
   "s": "قَدْ يَكُونُ هَذَا هُوَ السَّبَبَ. لَا تَسْهَرْ خَارِجَ الْبَيْتِ."
  },
  {
   "n": 3,
   "s": "إِذَنْ سَتَهْتَمُّ زَوْجَتُكَ بِكَ وَبِبَيْتِهَا، بِإِذْنِ اللَّهِ."
  },
  {
   "n": 2,
   "s": "يَعْتَقِدُ كَثِيرٌ مِنَ الشَّبَابِ أَنَّ الْحَيَاةَ الزَّوْجِيَّةَ بِلَا مُشْكِلَاتٍ."
  },
  {
   "n": 2,
   "s": "قَدْ تَحْدُثُ خِلَافَاتٌ بَيْنَ الزَّوْجَيْنِ."
  },
  {
   "n": 2,
   "s": "لِمَاذَا تَحْدُثُ مُشْكِلَاتٌ بَيْنَ الزَّوْجَيْنِ؟"
  },
  {
   "n": 2,
   "s": "الرَّجُلُ يُحِبُّ أَشْيَاءَ لَا تُحِبُّهَا الْمَرْأَةُ."
  },
  {
   "n": 2,
   "s": "زَوْجَتِي لَا تَسْتَمِعُ إِلَيَّ."
  },
  {
   "n": 2,
   "s": "تَتَكَلَّمُ مَعَ صَدِيقَاتِهَا فِي الْهَاتِفِ كَثِيرًا."
  },
  {
   "n": 2,
   "s": "يَقْضِي وَقْتًا طَوِيلًا خَارِجَ الْبَيْتِ."
  },
  {
   "n": 4,
   "s": "يَخْتَلِفُ نِظَامُ الْأُسْرَةِ الْآنَ عَنْ نِظَامِ الْأُسْرَةِ فِي الْمَاضِي."
  },
  {
   "n": 4,
   "s": "كَانَتِ الْأُسْرَةُ الْكَبِيرَةُ تَسْكُنُ فِي بَيْتٍ وَاحِدٍ كَبِيرٍ."
  },
  {
   "n": 4,
   "s": "اخْتَفَتِ الْأُسْرَةُ الْكَبِيرَةُ، وَظَهَرَتِ الْأُسْرَةُ الصَّغِيرَةُ."
  },
  {
   "n": 4,
   "s": "لَا يَرَوْنَ أَطْفَالَهُمْ إِلَّا قَلِيلًا."
  },
  {
   "n": 4,
   "s": "يُغَادِرُ الْأَوْلَادُ الْبَيْتَ فِي الصَّبَاحِ إِلَى الْمَدْرَسَةِ."
  },
  {
   "n": 4,
   "s": "تَبْقَى الْأُمُّ فِي الْبَيْتِ وَحْدَهَا مُعْظَمَ الْوَقْتِ."
  },
  {
   "n": 4,
   "s": "عِنْدَمَا تَرْجِعُ تَكُونُ مُتْعَبَةً."
  },
  {
   "n": 4,
   "s": "لَا تَجِدُ وَقْتًا لِتَجْلِسَ مَعَ أَطْفَالِهَا."
  }
 ],
